//! Android binding (D28, D35): UniFFI exports consumed by the Expo Kotlin
//! module. The engine sits behind one mutex; the platform implements
//! `NativeHost` (radio, hardware keystore, UI events). Host callbacks must
//! not call back into the core synchronously.
//!
//! This crate contains FFI glue generated by UniFFI, so it cannot forbid
//! unsafe code (section 20 exception).

use mesh_api::*;
use std::sync::{Arc, Mutex};

uniffi::setup_scaffolding!();

/// Implemented in Kotlin. Byte arrays are raw; UUIDs are 16-byte arrays.
#[uniffi::export(with_foreign)]
pub trait NativeHost: Send + Sync {
    fn start_advertising(&self, service_uuids: Vec<Vec<u8>>, beacon: Vec<u8>, power: u8);
    fn stop_advertising(&self);
    fn start_scanning(&self, service_uuids: Vec<Vec<u8>>);
    fn stop_scanning(&self);
    fn connect(&self, peer: u64);
    fn send_frame(&self, peer: u64, bytes: Vec<u8>) -> bool;
    fn disconnect(&self, peer: u64);
    fn lora_paired(&self) -> bool;
    fn wifi_p2p(&self) -> bool;
    fn lora_send(&self, bytes: Vec<u8>) -> bool;
    /// Open a Wi-Fi Direct link to the neighbour behind BLE handle `peer`
    /// (see `TransportHost::wifi_link`; `auth_token` is 32 bytes). The host
    /// reports the new link with `on_connected` carrying `"transport":"WifiP2p"`.
    fn wifi_link(
        &self,
        peer: u64,
        group_owner: bool,
        network_name: String,
        passphrase: String,
        auth_token: Vec<u8>,
    );
    /// Internet route: run or stop it (see `TransportHost::internet_config`).
    fn internet_config(&self, enabled: bool, config_json: String);
    /// Send one sealed envelope to a Nym address; false if the route cannot take it now.
    fn internet_send(&self, address: String, envelope: Vec<u8>) -> bool;
    /// Decrypted call audio for the speaker (Opus packets, about 12 times a
    /// second). Called with the core locked: queue it, never call back.
    fn call_audio(&self, data: Vec<u8>);
    // Keystore (slot: 0 relay db, 1 message db, 2 duress)
    fn ks_wrap(&self, slot: u8, plaintext: Vec<u8>) -> Option<Vec<u8>>;
    fn ks_unwrap(&self, slot: u8, wrapped: Vec<u8>) -> Option<Vec<u8>>;
    fn ks_hmac(&self, slot: u8, data: Vec<u8>) -> Option<Vec<u8>>;
    fn ks_store_biometric(&self, secret: Vec<u8>) -> bool;
    fn ks_load_biometric(&self) -> Option<Vec<u8>>;
    fn ks_counter_get(&self) -> u32;
    fn ks_counter_set(&self, v: u32);
    fn ks_destroy_all(&self);
    /// One JSON-encoded `Event`.
    fn emit(&self, event_json: String);
}

struct Bridge(Arc<dyn NativeHost>);

fn uuids(v: Vec<[u8; 16]>) -> Vec<Vec<u8>> {
    v.into_iter().map(|u| u.to_vec()).collect()
}

fn slot(s: KeySlot) -> u8 {
    match s {
        KeySlot::RelayDb => 0,
        KeySlot::MessageDb => 1,
        KeySlot::Duress => 2,
    }
}

impl TransportHost for Bridge {
    fn start_advertising(&self, u: Vec<[u8; 16]>, beacon: Vec<u8>, power: TxPower) {
        self.0.start_advertising(uuids(u), beacon, power as u8)
    }
    fn stop_advertising(&self) {
        self.0.stop_advertising()
    }
    fn start_scanning(&self, u: Vec<[u8; 16]>) {
        self.0.start_scanning(uuids(u))
    }
    fn stop_scanning(&self) {
        self.0.stop_scanning()
    }
    fn connect(&self, p: PeerHandle, _t: TransportKind) {
        self.0.connect(p)
    }
    fn send_frame(&self, p: PeerHandle, bytes: Vec<u8>) -> bool {
        self.0.send_frame(p, bytes)
    }
    fn disconnect(&self, p: PeerHandle) {
        self.0.disconnect(p)
    }
    fn capabilities(&self) -> Capabilities {
        Capabilities {
            wifi_p2p: self.0.wifi_p2p(),
            lora_paired: self.0.lora_paired(),
            tx_power_control: true,
        }
    }
    fn lora_send(&self, bytes: Vec<u8>) -> bool {
        self.0.lora_send(bytes)
    }
    fn wifi_link(
        &self,
        p: PeerHandle,
        group_owner: bool,
        network_name: String,
        passphrase: String,
        auth_token: [u8; 32],
    ) {
        self.0.wifi_link(
            p,
            group_owner,
            network_name,
            passphrase,
            auth_token.to_vec(),
        )
    }
    fn internet_config(&self, enabled: bool, config_json: String) {
        self.0.internet_config(enabled, config_json)
    }
    fn internet_send(&self, address: String, envelope: Vec<u8>) -> bool {
        self.0.internet_send(address, envelope)
    }
    fn call_audio(&self, data: Vec<u8>) {
        self.0.call_audio(data)
    }
}

impl Keystore for Bridge {
    fn wrap(&self, s: KeySlot, p: Vec<u8>) -> Result<Vec<u8>, KeystoreError> {
        self.0.ks_wrap(slot(s), p).ok_or(KeystoreError::Unavailable)
    }
    fn unwrap(&self, s: KeySlot, w: Vec<u8>) -> Result<Vec<u8>, KeystoreError> {
        self.0
            .ks_unwrap(slot(s), w)
            .ok_or(KeystoreError::Unavailable)
    }
    fn hmac(&self, s: KeySlot, d: Vec<u8>) -> Result<Vec<u8>, KeystoreError> {
        self.0.ks_hmac(slot(s), d).ok_or(KeystoreError::Unavailable)
    }
    fn store_biometric(&self, secret: Vec<u8>) -> Result<(), KeystoreError> {
        if self.0.ks_store_biometric(secret) {
            Ok(())
        } else {
            Err(KeystoreError::Unavailable)
        }
    }
    fn load_biometric(&self) -> Result<Vec<u8>, KeystoreError> {
        self.0.ks_load_biometric().ok_or(KeystoreError::Cancelled)
    }
    fn counter_get(&self) -> u32 {
        self.0.ks_counter_get()
    }
    fn counter_set(&self, v: u32) {
        self.0.ks_counter_set(v)
    }
    fn destroy_all(&self) {
        self.0.ks_destroy_all()
    }
}

impl EventSink for Bridge {
    fn emit(&self, e: Event) {
        if let Ok(j) = serde_json::to_string(&e) {
            self.0.emit(j)
        }
    }
}

#[derive(uniffi::Object)]
pub struct MeshCore {
    engine: Mutex<Engine>,
}

#[derive(Debug, thiserror::Error, uniffi::Error)]
pub enum OpenError {
    #[error("{msg}")]
    Failed { msg: String },
}

#[uniffi::export]
impl MeshCore {
    /// `dir`: app no-backup directory holding relay.db, message.db, keys.bin.
    #[uniffi::constructor]
    pub fn new(dir: String, host: Arc<dyn NativeHost>) -> Result<Arc<Self>, OpenError> {
        let b = Arc::new(Bridge(host));
        let h = Host {
            tx: b.clone(),
            ks: b.clone(),
            ev: b,
            clock: Arc::new(SystemClock),
            storage: Arc::new(FileStorage { dir }),
        };
        let engine = Engine::open(CoreConfig::default(), h)
            .map_err(|e| OpenError::Failed { msg: e.to_string() })?;
        Ok(Arc::new(Self {
            engine: Mutex::new(engine),
        }))
    }

    /// JSON method call (same surface as the browser build).
    pub fn call(&self, method: String, args_json: String) -> String {
        let mut e = self.engine.lock().unwrap_or_else(|p| p.into_inner());
        mesh_api::rpc::call_json(&mut e, &method, &args_json)
    }

    /// Microphone audio for the current call (Opus packets, see `calls`).
    pub fn call_send_audio(&self, data: Vec<u8>) {
        let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            self.engine
                .lock()
                .unwrap_or_else(|p| p.into_inner())
                .call_send_audio(&data)
        }));
    }

    pub fn on_frame(&self, peer: u64, bytes: Vec<u8>) {
        let r = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            self.engine
                .lock()
                .unwrap_or_else(|p| p.into_inner())
                .on_frame(peer, bytes)
        }));
        let _ = r;
    }

    /// Decode QR codes from an 8-bit luma camera frame (D25: in Rust).
    pub fn decode_qr(&self, width: u32, height: u32, luma: Vec<u8>) -> Vec<Vec<u8>> {
        std::panic::catch_unwind(|| mesh_handoff_decode(width, height, &luma)).unwrap_or_default()
    }

    /// Meshtastic ToRadio wrapping for an envelope (D26).
    pub fn lora_encode(&self, envelope: Vec<u8>, packet_id: u32) -> Option<Vec<u8>> {
        mesh_api::lora::encode_to_radio(&envelope, packet_id, 3)
    }

    /// Envelope from a Meshtastic FromRadio message, if it is ours.
    pub fn lora_decode(&self, from_radio: Vec<u8>) -> Option<Vec<u8>> {
        mesh_api::lora::decode_from_radio(&from_radio)
    }

    pub fn tick(&self) {
        let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            self.engine.lock().unwrap_or_else(|p| p.into_inner()).tick()
        }));
    }
}

fn mesh_handoff_decode(width: u32, height: u32, luma: &[u8]) -> Vec<Vec<u8>> {
    if luma.len() < (width as usize) * (height as usize) {
        return vec![];
    }
    mesh_handoff::qr_decode_luma(width, height, luma)
}
